import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { beforeEach, describe, expect, it, vi } from "vitest";
const { entitlements } = vi.hoisted(() => ({
  entitlements: { effectivePlan: "FREE" },
}));
vi.mock("@/components/workspace-quota", () => ({
  refreshWorkspaceAccess: vi.fn(),
  useWorkspaceEntitlements: () => entitlements,
}));
vi.mock("@/components/premium-upgrade-provider", () => ({
  usePremiumUpgrade: () => vi.fn(),
}));
import {
  LimitBanner,
  formatResetCountdown,
} from "../src/components/limit-banner";

const props = {
  used: 3,
  limit: 3,
  resetAt: "2026-10-31T00:00:00Z",
  upgradeHref: "/upgrade-fixture",
  allowancesHref: "/allowances-fixture",
};
describe("LimitBanner", () => {
  beforeEach(() => {
    entitlements.effectivePlan = "FREE";
  });
  it("does not render below the limit", () => {
    expect(
      renderToStaticMarkup(createElement(LimitBanner, { ...props, used: 2 })),
    ).toBe("");
  });
  it("renders a Free upgrade button and allowances link without a server countdown", () => {
    const html = renderToStaticMarkup(
      createElement(LimitBanner, { ...props, used: 5 }),
    );
    expect(html).toContain('aria-label="5 of 3 daily emails used"');
    expect(html).not.toContain('href="/upgrade-fixture"');
    expect(html).toMatch(/<button[^>]*>Get more sends<\/button>/);
    expect(html).toContain('href="/allowances-fixture"');
    expect(html).toContain('aria-expanded="false"');
    expect(html).toContain('inert=""');
    expect(html).not.toContain("until reset");
    expect(html).not.toContain("Ready");
  });
  it("preserves the supplied upgrade link for paid users", () => {
    entitlements.effectivePlan = "PAID";
    const html = renderToStaticMarkup(createElement(LimitBanner, props));
    expect(html).toContain('href="/upgrade-fixture"');
    expect(html).not.toMatch(/<button[^>]*>Get more sends<\/button>/);
  });
  it("calculates absolute remaining time and never goes negative", () => {
    const reset = Date.parse(props.resetAt);
    expect(formatResetCountdown(props.resetAt, reset - 3661000)).toBe(
      "01:01:01",
    );
    expect(formatResetCountdown(props.resetAt, reset - 100)).toBe("00:00:01");
    expect(formatResetCountdown(props.resetAt, reset)).toBe("Ready");
    expect(formatResetCountdown(props.resetAt, reset + 60000)).toBe("Ready");
  });
});
